#include <stdio.h>
#include <string.h>
#include <stdbool.h>

#define MAXLEN 65          /* the original binary limits both strings to < 65 */

int main(int argc, char *argv[])
{
    /* -------------------------------------------------------------
       Argument handling – the original program prints “USAGE” when
       the number of arguments is wrong or when either string is too
       long (>= 65 characters).  This matches the state‑machine checks
       for argc < 3 and for lengths >= 0x41.
       ------------------------------------------------------------- */
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    const char *pattern = argv[1];
    const char *text    = argv[2];

    size_t plen = strlen(pattern);
    size_t tlen = strlen(text);

    if (plen >= MAXLEN || tlen >= MAXLEN) {
        puts("USAGE");
        return 0;
    }

    /* -------------------------------------------------------------
       Dynamic‑programming table.
       dp[i][j] is true iff pattern[0..i‑1] matches text[0..j‑1].
       The original binary used a static 0x104×0x104 table; we keep
       the same logical size (65×65) which is sufficient for the
       enforced limits.
       ------------------------------------------------------------- */
    bool dp[MAXLEN][MAXLEN] = { false };

    dp[0][0] = true;                     /* empty pattern matches empty text */

    /* First column – pattern may start with '*' that can match an empty
       string.  The original code handled this with a loop that set
       dp[i][0] = dp[i‑1][0] when pattern[i‑1] == '*'. */
    for (size_t i = 1; i <= plen; ++i) {
        if (pattern[i - 1] == '*')
            dp[i][0] = dp[i - 1][0];
    }

    /* Fill the table */
    for (size_t i = 1; i <= plen; ++i) {
        for (size_t j = 1; j <= tlen; ++j) {
            char pc = pattern[i - 1];
            char tc = text[j - 1];

            if (pc == '*') {
                /* '*' matches zero characters (dp[i‑1][j]) or
                   one more character (dp[i][j‑1]) */
                dp[i][j] = dp[i - 1][j] || dp[i][j - 1];
            } else if (pc == '?') {
                /* '?' matches exactly one character */
                dp[i][j] = dp[i - 1][j - 1];
            } else {
                /* ordinary character must be equal */
                dp[i][j] = (pc == tc) && dp[i - 1][j - 1];
            }
        }
    }

    /* -------------------------------------------------------------
       Result – the original program prints “MATCH” when the final
       cell is true, otherwise “NO_MATCH”.
       ------------------------------------------------------------- */
    puts(dp[plen][tlen] ? "MATCH" : "NO_MATCH");
    return 0;
}
